function applyOfflineProgress(){const now=Date.now();if(!state.lastSeenAt){state.lastSeenAt=now;return}const elapsed=Math.max(0,now-state.lastSeenAt);state.lastSeenAt=now;if(!state.onboardingComplete){state.offlineElapsedMs=0;state.offlinePendingRounds=0;return}const interval=6*60*60*1000,total=(state.offlineElapsedMs||0)+elapsed,due=(state.offlinePendingRounds||0)+Math.floor(total/interval);state.offlineElapsedMs=total%interval;let completed=0;while(completed<8&&completed<due){const nextMatch=state.fixtures.find(m=>!m.played&&(m.home===state.clubId||m.away===state.clubId));if(!nextMatch)break;const round=nextMatch.round;state.fixtures.filter(m=>m.round===round&&!m.played).forEach(m=>play(m));state.clubs.forEach(c=>c.players.forEach(p=>{p.injury=Math.max(0,(p.injury||0)-1);p.fitness=clamp((p.fitness||70)+4,0,100)}));const own=state.fixtures.find(m=>m.round===round&&(m.home===state.clubId||m.away===state.clubId));if(own){const mine=ccur(),won=own.home===state.clubId?own.homeGoals>own.awayGoals:own.awayGoals>own.homeGoals,draw=own.homeGoals===own.awayGoals;if(own.home===state.clubId){const sponsorIncome=mine.sponsor&&mine.sponsor.season===state.season?mine.sponsor.matchIncome||0:0;const sm=stadiumMetrics(mine.facilities?.stadium||1,mine.fans||12000);mine.budget+=sm.estimatedRevenue-sm.maintenance+sponsorIncome;if(mine.sponsor&&mine.sponsor.season!==state.season)mine.sponsor=null}mine.fans=Math.max(1000,(mine.fans||12000)+(won?350:draw?120:-100))}refreshDailyMissions();state.missionProgress.matches=(state.missionProgress.matches||0)+1;state.week=Math.min(state.clubs.length*2-2,round+1);completed++}state.offlinePendingRounds=Math.max(0,due-completed);if(completed){log("در زمان دوربودن شما، "+completed+" هفته لیگ به‌صورت خودکار شبیه‌سازی شد.","پیشرفت آفلاین")}try{localStorage.setItem(SKEY,JSON.stringify(state))}catch(e){}}
applyOfflineProgress();
function save(show=true){try{state.lastSeenAt=Date.now();localStorage.setItem(SKEY,JSON.stringify(state));if(show)toast("بازی روی همین دستگاه ذخیره شد")}catch(e){toast("ذخیره‌سازی در دسترس نیست")}}
function ccur(){return state.clubs.find(c=>c.id===state.clubId)}function club(id){return state.clubs.find(c=>c.id===id)}function allp(){return state.clubs.flatMap(c=>c.players)}function log(text,type){state.logs.push({text,type:type||"باشگاه",date:new Date().toLocaleDateString("fa-IR")});if(state.logs.length>100)state.logs.shift()}function commit(msg){save(false);render();if(msg)toast(msg)}
function refreshDailyMissions(){const today=new Date().toISOString().slice(0,10);if(state.missionDate!==today){state.missionDate=today;state.missionProgress={matches:0,training:0,recruits:0,predictions:0,youth:0};state.missionClaims={}}state.missionProgress=state.missionProgress||{matches:0,training:0,recruits:0,predictions:0,youth:0};state.missionClaims=state.missionClaims||{}}
function missionsView(){refreshDailyMissions();const tasks=[{id:"matches",title:"حضور در یک مسابقه",desc:"یک هفته از لیگ را کامل کن.",need:1,reward:18000,progress:state.missionProgress.matches||0},{id:"training",title:"تمرین تیم",desc:"یک جلسه تمرین برگزار کن.",need:1,reward:12000,progress:state.missionProgress.training||0},{id:"recruits",title:"تقویت فهرست",desc:"یک بازیکن به باشگاه اضافه کن.",need:1,reward:25000,progress:state.missionProgress.recruits||0},{id:"predictions",title:"پیش‌بینی رایگان",desc:"یک نتیجه را پیش‌بینی کن؛ ورود کاملاً رایگان است.",need:1,reward:20000,progress:state.missionProgress.predictions||0},{id:"youth",title:"استعدادیابی",desc:"یک بازیکن جوان از آکادمی جذب کن.",need:1,reward:0,diamonds:3,progress:state.missionProgress.youth||0}];return '<div class="hero-card"><div><span class="eyebrow">DAILY OBJECTIVES</span><h2>ماموریت‌های روزانه</h2><p>ماموریت‌ها رایگان‌اند؛ پاداش فقط پس از انجام شرط واقعی هر ماموریت قابل دریافت است.</p></div><div class="hero-icon">✦</div></div><div class="grid two-col">'+tasks.map(t=>{const done=t.progress>=t.need,claimed=!!state.missionClaims[t.id];return '<section class="panel mission-card"><div class="panel-head"><h3>'+t.title+'</h3><span class="pill">+'+(t.diamonds?num(t.diamonds)+' الماس':money(t.reward))+'</span></div><p class="muted">'+t.desc+'</p><div class="mission-progress"><span style="width:'+Math.min(100,t.progress/t.need*100)+'%"></span></div><small>پیشرفت: '+num(Math.min(t.progress,t.need))+'/'+num(t.need)+'</small><button class="btn '+(done&&!claimed?"primary":"ghost")+'" data-action="claim-mission" data-id="'+t.id+'" '+(!done||claimed?"disabled":"")+'>'+(claimed?"دریافت‌شده":done?"دریافت پاداش":"هنوز کامل نشده")+'</button></section>'}).join("")+'</div>'}
function stat(l,v,n){return '<article class="stat-card"><div class="stat-label">'+l+'</div><div class="stat-value">'+v+'</div><div class="stat-note">'+(n||"")+'</div></article>'}
function table(){return state.clubs.slice().sort((a,b)=>b.points-a.points||((b.gf-b.ga)-(a.gf-a.ga))||b.gf-a.gf).map((c,i)=>'<tr><td><span class="rank">'+num(i+1)+'</span></td><td>'+c.crest+' <button class="club-link" data-club-profile="'+c.id+'">'+c.name+'</button>'+(c.id===state.clubId?' <span class="pill">تیم شما</span>':'')+'</td><td>'+num(c.played)+'</td><td>'+num(c.w)+'</td><td>'+num(c.d)+'</td><td>'+num(c.l)+'</td><td>'+num(c.gf-c.ga)+'</td><td><b>'+num(c.points)+'</b></td></tr>').join("")}
function tableHtml(){return '<div class="table-wrap"><table><thead><tr><th>#</th><th>باشگاه</th><th>بازی</th><th>برد</th><th>مساوی</th><th>باخت</th><th>تفاضل</th><th>امتیاز</th></tr></thead><tbody>'+table()+'</tbody></table></div>'}
