if(!c.aiTactics){const seed=stableSeed(c.id);const styles=["balanced","possession","counter","wing","direct"];c.aiTactics={style:styles[seed%styles.length],build:["short","mixed","long"][(seed>>>4)%3],pressing:35+(seed%56),tempo:40+((seed>>>5)%45),width:35+((seed>>>8)%55),line:35+((seed>>>11)%55),defenseStyle:["pressure","deep","balanced"][(seed>>>14)%3],containment:["center","wide"][(seed>>>17)%2],mentality:["defensive","balanced","attacking"][(seed>>>20)%3]}}
