const he=tacticalEdge(H,A),ae=tacticalEdge(A,H);
function chance(x){return Math.random()<clamp(x,0,1)}
function poisson(lambda){const limit=Math.exp(-lambda);let k=0,prod=1;do{k++;prod*=Math.random()}while(prod>limit&&k<9);return Math.max(0,k-1)}
function expected(team,opp,edge,oppEdge,homeAdv){
const fitnessPenalty=Math.max(0,70-team.fitness)*.0035;
const matchup=(team.attack-opp.defense)*.018+(team.attack-team.keeper)*.004;
return clamp(1.12+matchup+edge.atk-oppEdge.def+homeAdv-fitnessPenalty,.12,3.25)
}
const hx=expected(H,A,he,ae,.14),ax=expected(A,H,ae,he,.02);
const hg=poisson(hx),ag=poisson(ax);
m.played=true;m.homeGoals=hg;m.awayGoals=ag;m.events=[];
m.stats={home:{xg:Number(hx.toFixed(2)),possession:clamp(Math.round(he.poss+(avg(H.ps,"pass")-avg(A.ps,"pass"))*.22),25,75),shots:0,onTarget:0,corners:0},away:{xg:Number(ax.toFixed(2)),possession:clamp(Math.round(ae.poss+(avg(A.ps,"pass")-avg(H.ps,"pass"))*.22),25,75),shots:0,onTarget:0,corners:0}};
m.stats.away.possession=100-m.stats.home.possession;
function scorer(team){const candidates=team.ps.filter(p=>p.code!=="GK");if(!candidates.length)return team.ps[0];const weights=candidates.map(p=>Math.max(1,(p.finishing||35)*.5+(p.shoot||35)*.25+(p.positioning||35)*.15+(p.pace||35)*.1));let r=Math.random()*weights.reduce((sum,v)=>sum+v,0);for(let i=0;i<candidates.length;i++){r-=weights[i];if(r<=0)return candidates[i]}return candidates[0]}
function assist(team,sc){const candidates=team.ps.filter(p=>p.id!==sc?.id&&p.code!=="GK");return candidates.length?candidates[Math.floor(Math.random()*candidates.length)]:null}
function addGoals(team,count,side){
const stats=m.stats[side];
for(let i=0;i<count;i++){const p=scorer(team),as=assist(team,p),minute=5+Math.floor(Math.random()*86);if(p){p.goals=(p.goals||0)+1}if(as)as.assists=(as.assists||0)+1;stats.shots++;stats.onTarget++;m.events.push({minute,type:"goal",team:team.club.id,player:p?.id||null,playerName:p?.name||"گل‌زن نامشخص",assist:as?.name||null,text:"گل "+(p?.name||"تیم")+(as?" با پاس "+as.name:"")})}
for(let i=0;i<Math.max(2,count+2);i++){stats.shots++;if(chance(.34))stats.onTarget++;if(chance(.28))stats.corners++}
}
addGoals(H,hg,"home");addGoals(A,ag,"away");m.stats.home.saves=Math.max(0,m.stats.away.onTarget-ag);m.stats.away.saves=Math.max(0,m.stats.home.onTarget-hg);function addKeeperSaves(team,count){const keeper=team.ps.find(p=>p.code==="GK")||team.club.players.find(p=>p.code==="GK");for(let i=0;i<count;i++)m.events.push({minute:7+Math.floor(Math.random()*82),type:"save",team:team.club.id,player:keeper?.id||null,playerName:keeper?.name||"دروازه‌بان",text:(keeper?.name||"دروازه‌بان")+" ضربه را مهار کرد"})}addKeeperSaves(H,m.stats.home.saves);addKeeperSaves(A,m.stats.away.saves);
for(let minute=3;minute<=90;minute+=Math.floor(7+Math.random()*7)){
if(chance(.6)){const home=chance(.5),team=home?H:A,opp=home?A:H,side=home?"home":"away";const attackers=team.ps.filter(p=>p.code!=="GK");const attacker=attackers.length?attackers[Math.floor(Math.random()*attackers.length)]:null;const defenders=opp.ps.filter(p=>["GK","CB","RB","LB","RWB","LWB","CDM"].includes(p.code));const defender=defenders.sort((x,y)=>(y.tackling+y.marking+y.positioning+y.strength)-(x.tackling+x.marking+x.positioning+x.strength))[0];if(attacker&&defender){const attackScore=attacker.dribbling+attacker.acceleration+attacker.balance,defScore=defender.tackling+defender.positioning+defender.strength;const win=attackScore>defScore+Math.random()*40;m.events.push({minute,type:win?"attack":"tackle",team:team.club.id,player:attacker.id,playerName:attacker.name,text:win?attacker.name+" از فشار مدافع عبور کرد":defender.name+" با تکل توپ را گرفت"});if(win)team===H?m.stats.home.shots++:m.stats.away.shots++}}
}
m.events.sort((x,y)=>x.minute-y.minute);m.events=m.events.slice(0,30);if(h.id!==state.clubId&&a.id!==state.clubId)m.events=[];
function upd(c,gf,ga){c.played++;c.gf+=gf;c.ga+=ga;if(gf>ga){c.w++;c.points+=3}else if(gf===ga){c.d++;c.points++}else c.l++}
if(leagueMatch){upd(h,hg,ag);upd(a,ag,hg)}
[H,A].forEach(team=>team.club.players.forEach(p=>{if(team.ps.includes(p)){p.apps=(p.apps||0)+1;p.fitness=clamp((p.fitness||75)-(p.starter?10:4),10,100);if(chance(.009))p.injury=1+Math.floor(Math.random()*3)}}));
if(leagueMatch){const pred=state.predictions[m.id];if(pred&&!pred.rewarded){if(pred.home===hg&&pred.away===ag){ccur().budget+=100000;log("پیش‌بینی دقیق بود؛ "+money(100000)+" جایزه درون‌بازی دریافت شد","پیش‌بینی")}pred.rewarded=true}}
