function next(){refreshDailyMissions();let c=ccur(),m=state.fixtures.find(x=>!x.played&&(x.home===c.id||x.away===c.id));if(!m){toast("مسابقه‌ای باقی نمانده است.");return}const round=m.round;state.fixtures.filter(x=>x.round===round&&!x.played).forEach(x=>play(x));let predictionReward=0;state.fixtures.filter(x=>x.round===round&&x.played&&state.predictions[x.id]&&!state.predictions[x.id].settled).forEach(x=>{const p=state.predictions[x.id],exact=p.home===x.homeGoals&&p.away===x.awayGoals,outcome=(p.home>p.away?1:p.home<p.away?-1:0)===(x.homeGoals>x.awayGoals?1:x.homeGoals<x.awayGoals?-1:0);p.settled=true;p.correct=exact||outcome;const reward=exact?30000:outcome?8000:0;if(reward){predictionReward+=reward;log("پیش‌بینی "+club(x.home).name+" و "+club(x.away).name+" درست بود؛ "+money(reward)+" پاداش","پیش‌بینی")}});if(predictionReward)ccur().budget+=predictionReward;state.clubs.forEach(x=>x.players.forEach(p=>{p.injury=Math.max(0,p.injury-1);p.fitness=clamp(p.fitness+4,0,100)}));const ownMatch=state.fixtures.find(x=>x.round===round&&(x.home===state.clubId||x.away===state.clubId));if(ownMatch){state.missionProgress.matches=(state.missionProgress.matches||0)+1;const mine=ccur(),won=(ownMatch.home===state.clubId?ownMatch.homeGoals>ownMatch.awayGoals:ownMatch.awayGoals>ownMatch.homeGoals),draw=ownMatch.homeGoals===ownMatch.awayGoals;if(ownMatch.home===state.clubId){const sm=stadiumMetrics(mine.facilities?.stadium||1,mine.fans||12000),revenue=sm.estimatedRevenue-sm.maintenance,sponsorIncome=mine.sponsor&&mine.sponsor.season===state.season?mine.sponsor.matchIncome||0:0;mine.budget+=revenue+sponsorIncome;if(mine.sponsor&&mine.sponsor.season!==state.season)mine.sponsor=null;log("درآمد بازی خانگی: "+money(revenue+sponsorIncome)+(sponsorIncome?" (شامل حامی مالی)":""),"درآمد باشگاه")}mine.fans=Math.max(1000,(mine.fans||12000)+(won?350:draw?120:-100))}state.week=Math.min(state.clubs.length*2-2,round+1);commit("هفته "+num(round)+" تکمیل شد؛ نتیجه تیم تو: "+club(m.home).name+" "+m.homeGoals+" - "+m.awayGoals+" "+club(m.away).name)}
function newSeason(){
if(state.fixtures.some(m=>!m.played)){toast("برای شروع فصل بعد باید تمام مسابقات فصل جاری انجام شده باشند.");return}
const standings=state.clubs.slice().sort((a,b)=>b.points-a.points||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf),champion=standings[0];
log("فصل "+num(state.season)+" تمام شد؛ قهرمان: "+champion.name,"افتخارات");state.season++;state.week=1;
state.clubs.forEach(c=>{c.points=0;c.w=0;c.d=0;c.l=0;c.gf=0;c.ga=0;c.played=0;c.budget+=250000;if(c.sponsor&&c.sponsor.season<state.season+1)c.sponsor=null;
c.players=c.players.filter(p=>{if(p.age>=40){log(p.name+" در سن "+num(p.age)+" سالگی بازنشسته شد","بازنشستگی");return false}return true});
c.players.forEach(p=>{p.age++;p.fitness=clamp(p.fitness+20,0,100);p.contract=Math.max(1,(p.contract||1)-1);
if(p.age<24&&calculateOverall(p)<p.potential&&Math.random()<.45){const growth=TRAINABLE_SKILLS[Math.floor(Math.random()*TRAINABLE_SKILLS.length)];p[growth]=clamp(p[growth]+1,10,Math.min(110,p.potential))}
if(p.age>=34){const decline=p.code==="GK"?["reaction","agility"]:["pace","acceleration","agility","stamina"];if(Math.random()<.3){const key=decline[Math.floor(Math.random()*decline.length)];p[key]=clamp(p[key]-1,10,110)}}
p.defense=Math.round((p.tackling+p.marking+p.positioning)/3);p.rating=calculateOverall(p);p.value=playerValue(p)
})});
state.fixtures=fixtures(state.clubs);state.cup=cupSeed(state.clubs,state.season);state.predictions={};state.market=marketSeed(state);
commit("فصل جدید آغاز شد؛ قهرمان فصل قبل: "+champion.name)
}function cupView(){const cup=state.cup|| (state.cup=cupSeed(state.clubs,state.season));const labels={1:"یک‌شانزدهم نهایی · ۳۲ تیم",2:"یک‌هشتم نهایی",3:"یک‌چهارم نهایی",4:"نیمه‌نهایی",5:"فینال",6:"پایان مسابقات"};const rows=(cup.matches||[]).map(m=>{const h=club(m.home),a=club(m.away);return '<div class="match-row"><div class="match-team"><span class="club-badge">'+h.crest+'</span><b>'+h.name+'</b></div><div class="match-center"><div class="fixture-score">'+(m.played?num(m.homeGoals)+' - '+num(m.awayGoals):'— : —')+'</div><small>'+(m.played?(m.winner?'صعود: '+club(m.winner).name:'پایان‌یافته'):labels[m.round]||'جام حذفی')+'</small></div><div class="match-team"><b>'+a.name+'</b><span class="club-badge">'+a.crest+'</span></div></div>'}).join('');const hist=(cup.history||[]).map(r=>'<section class="panel" style="margin-top:12px"><h3>'+labels[r.round]+'</h3>'+r.matches.map(m=>'<div class="list-row"><span>'+club(m.home).name+' '+num(m.homeGoals)+' - '+num(m.awayGoals)+' '+club(m.away).name+'</span><small>صعود: '+club(m.winner).name+'</small></div>').join('')+'</section>').join('');return '<div class="hero-card"><div><span class="eyebrow">KNOCKOUT COMPETITION</span><h2>🏆 جام حذفی فصل '+num(cup.season)+'</h2><p>۳۲ باشگاه، بازی‌های حذفی و یک قهرمان. تساوی در وقت قانونی با ضربات پنالتی شبیه‌سازی می‌شود. نتایج جام از جدول لیگ جدا هستند.</p><div class="btn-row">'+(cup.champion?'<span class="pill good">قهرمان: '+club(cup.champion).name+'</span>':'<button class="btn primary" data-action="cup-play-round">'+(cup.round===5?'شبیه‌سازی فینال':'انجام '+(labels[cup.round]||'مرحله بعد'))+'</button>')+'<button class="btn ghost" data-action="cup-new">شروع دوباره جام</button></div></div><div class="hero-icon">🏆</div></div><div class="grid stats-grid">'+stat("مرحله",labels[cup.round]||"پایان", "فصل "+num(cup.season))+stat("تعداد بازی این مرحله",num((cup.matches||[]).length),"مسابقات حذفی")+stat("بازی‌های انجام‌شده",num((cup.matches||[]).filter(m=>m.played).length),"در مرحله فعلی")+stat("وضعیت",cup.champion?"قهرمان مشخص شد":"در جریان","مسابقه‌ها آفلاین هستند")+'</div><section class="panel"><div class="panel-head"><h3>'+(labels[cup.round]||"مرحله نهایی")+'</h3><span class="muted">نتایج جام مستقل از لیگ</span></div>'+(rows||'<div class="empty">هنوز مسابقه‌ای ثبت نشده.</div>')+'</section>'+hist+(cup.champion?'<section class="panel" style="margin-top:12px;text-align:center"><div style="font-size:42px">🏆</div><h2>قهرمان جام حذفی</h2><h3>'+club(cup.champion).crest+' '+club(cup.champion).name+'</h3><p class="muted">با پایان فصل لیگ، جام جدید برای فصل بعد ساخته می‌شود.</p></section>':'<div class="notice">نکته: این جام فعلاً در نسخه آفلاین بازی می‌شود؛ رقابت با کاربران واقعی به سرور آنلاین نیاز دارد.</div>')}
function convertDiamonds(){const c=ccur(),raw=prompt("چند الماس تبدیل شود؟ هر ۱ الماس برابر ۸ سکه است.");if(raw===null)return;const amount=Number(raw);if(!Number.isInteger(amount)||amount<1||amount>c.diamonds){toast("تعداد الماس معتبر نیست.");return}c.diamonds-=amount;c.budget+=amount*8000;log(num(amount)+" الماس به "+num(amount*8)+" سکه تبدیل شد","تبدیل ارز");commit("تبدیل ارز با نرخ ۱ الماس = ۸ سکه انجام شد.")}
