const cost=next.cost;
if(c.budget<cost){toast("بودجه کافی نیست؛ هزینه ارتقای بعدی "+money(cost)+" است.");return}
c.budget-=cost;f[key]=level+1;
log("ارتقای "+({stadium:"ورزشگاه",training:"مرکز تمرین",academy:"آکادمی جوانان"}[key])+" به مرحله "+f[key]+" رسید؛ هزینه "+money(cost),"امکانات");
